INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (361, 1, '인증 서비스의 일', 'OpenStack 의 **Keystone** 이 맡은 일로 알맞은 것은 무엇일까요?', '누구인지 확인하고 무엇을 할 수 있는지를 다뤄요.', NULL, NULL, '[]', 'choice', '["가상 머신 이미지를 등록하고 가져오는 일", "서버에 붙이는 영구 블록 볼륨을 만드는 일", "사용자 인증, 토큰 발급, 서비스 카탈로그 제공", "가상 네트워크와 라우터를 만들어 주는 일"]', 2, 'Keystone 문서는 인증(플러그인), 토큰 서비스, 서비스 위치를 알려 주는 카탈로그, 권한 확인(정책)을 Keystone 이 맡는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 2, '프로젝트란', 'Keystone 에서 **프로젝트(project)** 는 무엇의 기본 단위일까요?', '서버, 볼륨 같은 자원이 누구 것인지를 나눠요.', NULL, NULL, '[]', 'choice', '["사용자 비밀번호를 저장해 두는 단위", "자원 소유를 나누는 기본 단위", "네트워크 패킷을 거르는 규칙의 단위", "서버의 CPU 크기를 정해 두는 단위"]', 1, 'Keystone 문서는 "프로젝트는 OpenStack 에서 소유의 기본 단위"라고 설명합니다. 자원은 프로젝트에 속합니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 3, '도메인이란', 'Keystone 의 **도메인(domain)** 에 대한 설명으로 알맞은 것은 무엇일까요?', '프로젝트보다 한 단계 위의 묶음이에요.', NULL, NULL, '[]', 'choice', '["프로젝트·사용자·그룹을 담는 상위 컨테이너", "서버에 붙는 인터넷 주소(DNS 이름) 하나", "서버를 만드는 규격표 한 가지", "볼륨 백업이 저장되는 장소"]', 0, '문서는 도메인을 "프로젝트, 사용자, 그룹의 상위 컨테이너"라고 설명합니다. 각 항목은 정확히 한 도메인에 속합니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 4, '사용자란', 'Keystone 의 **사용자(user)** 는 무엇을 나타낼까요?', '개별 개체 하나예요.', NULL, NULL, '[]', 'choice', '["서버 안에서 돌아가는 프로그램 하나", "프로젝트에 붙은 비용 청구서", "여러 서비스의 접속 주소 목록", "개별 API 사용자 한 명(또는 한 주체)"]', 3, '문서는 사용자를 "개별 API 소비자(individual API consumer)"라고 설명하며, 사용자는 한 도메인에 속합니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 5, '그룹이란', 'Keystone 의 **그룹(group)** 은 무엇일까요?', '여러 사람을 한 번에 다루기 위한 거예요.', NULL, NULL, '[]', 'choice', '["프로젝트들을 모아 둔 컨테이너", "서버들을 모아 둔 컨테이너", "사용자들을 모아 둔 컨테이너", "토큰들을 모아 둔 컨테이너"]', 2, '문서는 그룹을 "사용자 모음을 나타내는 컨테이너"라고 설명합니다. 그룹도 한 도메인이 소유합니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 6, '역할이란', 'Keystone 의 **역할(role)** 은 무엇을 정할까요?', '무엇을 할 수 있는지의 수준이에요.', NULL, NULL, '[]', 'choice', '["사용자가 로그인하는 비밀번호의 길이", "최종 사용자가 얻을 수 있는 권한(인가)의 수준", "서버가 만들어지는 물리 서버의 위치", "이미지가 저장되는 파일 형식"]', 1, '문서는 "역할은 최종 사용자가 얻을 수 있는 인가 수준을 정한다"고 설명합니다. 도메인이나 프로젝트 수준에서 사용자 또는 그룹에 줄 수 있습니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 7, '역할 부여의 구성', 'Keystone 의 **역할 부여(role assignment)** 는 무엇의 조합일까요?', '세 가지 요소가 모여요.', NULL, NULL, '[]', 'choice', '["역할, 자원, 신원의 조합", "토큰, 엔드포인트, 서비스 이름", "이미지, 볼륨, 스냅샷", "네트워크, 서브넷, 포트"]', 0, '문서는 역할 부여를 "역할(Role), 자원(Resource), 신원(Identity)의 3-튜플"이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 8, '이름이 겹칠 수 있는 범위', '프로젝트 이름은 어느 범위 안에서 유일해야 할까요?', '프로젝트는 도메인에 속해요.', NULL, NULL, '[]', 'choice', '["모든 도메인을 통틀어 하나뿐이어야 한다", "이름은 겹쳐도 되고 어디서도 유일할 필요가 없다", "클라우드 전체에서 사용자 이름과도 겹치면 안 된다", "같은 도메인 안에서만 유일하면 된다"]', 3, '문서는 프로젝트 이름이 해당 도메인 안에서만 유일하면 된다고 설명합니다. 도메인을 지정하지 않으면 기본(default) 도메인을 씁니다.', NULL, NULL, NULL, '[{"title": "Keystone 구조", "url": "https://docs.openstack.org/keystone/latest/getting-started/architecture.html"}]'),
  (361, 9, '기본 토큰 형식', 'Keystone 의 기본 **토큰 제공자** 와 그 특징으로 알맞은 것은 무엇일까요?', '이름에 독일 작가의 이름이 들어가요.', NULL, NULL, '[]', 'choice', '["기본은 ldap 이며 모든 토큰을 데이터베이스에 저장한다", "기본은 plain 이며 토큰을 누구나 읽을 수 있다", "fernet 이 기본이며 토큰을 서버에 저장하지 않아도 된다", "기본 토큰은 없어서 매번 비밀번호를 보내야 한다"]', 2, '토큰 제공자 설정의 기본값은 fernet 입니다. Fernet 토큰은 저장(영속화)이 필요 없습니다. 다만 가진 쪽이 접근할 수 있는 bearer 토큰이라 노출되지 않게 지켜야 합니다.', NULL, NULL, NULL, '[{"title": "Keystone 토큰 제공자", "url": "https://docs.openstack.org/keystone/latest/admin/token-provider.html"}]'),
  (361, 10, '프로젝트 만들기', '프로젝트 `new-project` 를 도메인 `default` 에 **만드는** 명령입니다. 빈칸을 채우세요.', '만든다는 동사예요.', NULL, NULL, '[]', 'fill', '["create", "add", "new", "make"]', NULL, '문서 예시는 `openstack project create --description ''my new project'' new-project --domain default` 입니다.', '[0]', 'openstack project {0} --description ''my new project'' new-project --domain default', NULL, '[{"title": "Keystone 프로젝트·사용자·역할 관리", "url": "https://docs.openstack.org/keystone/latest/admin/cli-manage-projects-users-and-roles.html"}]'),
  (361, 11, '역할 부여하기', '사용자 `alice` 에게 프로젝트 `demo` 의 `member` 역할을 **주는** 명령입니다. 빈칸을 채우세요.', '역할을 더한다는 뜻이에요.', NULL, NULL, '[]', 'fill', '["add", "grant", "give", "attach"]', NULL, '문서 예시는 `openstack role add --user USER_NAME --project PROJECT_NAME ROLE_NAME` 입니다. 부여 결과는 `openstack role assignment list` 로 확인합니다.', '[0]', 'openstack role {0} --user alice --project demo member', NULL, '[{"title": "Keystone 프로젝트·사용자·역할 관리", "url": "https://docs.openstack.org/keystone/latest/admin/cli-manage-projects-users-and-roles.html"}]'),
  (361, 12, '사용자에게 프로젝트 권한 주기', '새 프로젝트에서 새 사용자가 일할 수 있게 하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '프로젝트와 사용자가 있어야 역할을 줄 수 있어요.', NULL, NULL, '[]', 'order', '["프로젝트를 만든다", "사용자를 만든다", "줄 역할을 정한다(목록에서 고르거나 새로 만든다)", "사용자에게 프로젝트의 역할을 부여한다", "역할 부여 목록으로 결과를 확인한다"]', NULL, '프로젝트와 사용자를 만든 뒤 역할을 정해 `role add` 로 부여하고, `role assignment list` 로 확인합니다. 문서의 명령 흐름을 큰 줄기로 이은 순서입니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "Keystone 프로젝트·사용자·역할 관리", "url": "https://docs.openstack.org/keystone/latest/admin/cli-manage-projects-users-and-roles.html"}]');
